zscore <- function(x){ m<-mean(x,na.rm=TRUE); s<-sd(x,na.rm=TRUE)
  if(is.na(s)||s==0) return(rep(0,length(x))); (x-m)/s }

run_pca <- function(df, zc){
  cc  <- df[complete.cases(df[,zc,drop=FALSE]),]
  fit <- prcomp(cc[,zc,drop=FALSE], center=TRUE, scale.=TRUE)
  l1  <- fit$rotation[,1]; flip <- if(mean(l1) < 0) -1 else 1
  list(fit=fit, years=cc$year, pc1=fit$x[,1]*flip, loadings=l1*flip,
       var_exp=fit$sdev^2/sum(fit$sdev^2), n=nrow(cc))
}

# sup-F helpers that reuse the CANONICAL .chow_F_reg (level+trend, df1=2) with
# the SAME interior/trim as chow_sweep, so nulls & bootstraps are like-for-like.
.ks_interior <- function(n, trim=0.15, min_seg=3){
  lo <- max(min_seg, floor(trim*n)); hi <- min(n-min_seg, n-floor(trim*n)); lo:hi
}
supF_max <- function(y, trim=0.15, min_seg=3){
  n<-length(y); t<-seq_len(n); ks<-.ks_interior(n,trim,min_seg)
  max(vapply(ks, function(k) .chow_F_reg(y,t,k,min_seg), numeric(1)), na.rm=TRUE)
}
supF_peakyear <- function(y, year, trim=0.15, min_seg=3){
  n<-length(y); t<-seq_len(n); ks<-.ks_interior(n,trim,min_seg)
  f<-vapply(ks, function(k) .chow_F_reg(y,t,k,min_seg), numeric(1))
  year[ks[which.max(f)]]
}

# mean-shift Chow (df1=1) — ONLY to show the contrasting ~86-100 statistic.
.rss_mean <- function(y){ s<-sum((y-mean(y))^2); if(is.na(s)) 0 else s }
chow_F_meanshift <- function(y, k, min_seg=3){
  n<-length(y); if(k<min_seg||k>n-min_seg) return(NA_real_)
  rss_pool <- .rss_mean(y); rss_split <- .rss_mean(y[1:k])+.rss_mean(y[(k+1):n])
  if(rss_split<=0) return(NA_real_)
  ((rss_pool-rss_split)/1)/(rss_split/(n-2))
}
supF_meanshift <- function(y, year, trim=0.15, min_seg=3){
  n<-length(y); ks<-.ks_interior(n,trim,min_seg)
  f<-vapply(ks, function(k) chow_F_meanshift(y,k,min_seg), numeric(1))
  list(peak_year=year[ks[which.max(f)]], peak_F=max(f,na.rm=TRUE), curve=data.frame(year=year[ks],F=f))
}

