# 3a. Canonical LEVEL+TREND sup-F (df1=2) with iid permutation p
CS <- chow_sweep(year=P$years, y=P$pc1, trim=0.15, nperm=NPERM, seed=SEED)
cat(sprintf("\n=== CANONICAL LEVEL+TREND sup-F (df1=2) ===\n"))
cat(sprintf("Break year        = %d\n", CS$peak_year))
