cat(sprintf("sup-F WALD         = %.2f   [<- QUOTE THIS: df1 * F, what sctest() returns]\n", 2*CS$peak_F))
cat(sprintf("5%% pointwise crit = %.2f\n", CS$crit_5pct))
cat(sprintf("perm p (iid)      = %.4f  (%d draws)\n", CS$perm_p, NPERM))
cat(sprintf("slope before/after= %.4f / %.4f\n", CS$slope_before, CS$slope_after))
write.csv(CS$curve, file.path(OUT,"canonical_fsweep_leveltrend.csv"), row.names=FALSE)

# 3b. Mean-shift (df1=1) contrast — the ~86-100 statistic (NOT canonical)
MS <- supF_meanshift(P$pc1, P$years)
