# --- segmented (two-regime linear-trend) fit at the canonical break ---------
# Used both by the block-bootstrap CI (3d) and by the "fair" AR(1) null (3c).
yy <- P$pc1[order(P$years)]; yr <- sort(P$years); n <- length(yy); t <- seq_len(n)
kk <- CS$peak_k
fit1 <- lm(yy[1:kk] ~ t[1:kk]); fit2 <- lm(yy[(kk+1):n] ~ t[(kk+1):n])
fitted_seg <- c(fitted(fit1), fitted(fit2)); resid_seg <- yy - fitted_seg

# 3c. AR(1)-NULL p — autocorrelation-robust Monte-Carlo null.
#   The sup-F NULL hypothesis is a SINGLE regime: y = a + b*t + e. So the null
#   DGP is the pooled single-trend fit plus AR(1) innovations; we simulate NSIM
#   paths, recompute the canonical sup-F max on each, p = Pr(sim sup-F >= obs).
#   Two ways to estimate the nuisance AR(1) persistence, reported as a range:
#     (i) POOLED-residual phi  = AR(1) of residuals from ONE trend line. The
#         break is still in those residuals, so phi is inflated -> this null is
#         DELIBERATELY CONSERVATIVE (an upper bound on p).
#    (ii) SEGMENTED-residual phi = AR(1) of residuals NET of the break (two-
#         regime fit). This isolates genuine short-run autocorrelation from
#         break-induced persistence -> a FAIRER, more powerful null.
m_pool   <- lm(yy ~ t); fit_pool <- fitted(m_pool); res_pool <- residuals(m_pool)
phi_pool <- as.numeric(ar(res_pool,  order.max=1, aic=FALSE, method="yule-walker")$ar)
phi_seg  <- as.numeric(ar(resid_seg, order.max=1, aic=FALSE, method="yule-walker")$ar)
sd_pool  <- sd(res_pool)  * sqrt(max(1e-6, 1 - phi_pool^2))   # AR(1) innovation sd
sd_seg   <- sd(resid_seg) * sqrt(max(1e-6, 1 - phi_seg^2))
ar1_null_p <- function(phi, sdi){
  sim <- replicate(NSIM, supF_max(fit_pool + as.numeric(arima.sim(list(ar=phi), n=n, sd=sdi))))
  mean(sim >= CS$peak_F)
}
set.seed(SEED); p_ar1_pooled <- ar1_null_p(phi_pool, sd_pool)   # conservative
set.seed(SEED); p_ar1_seg    <- ar1_null_p(phi_seg,  sd_seg)    # fair
cat(sprintf("\n=== AR(1)-NULL sup-F test (single-trend-line null + AR(1) innovations) ===\n"))
cat(sprintf("pooled-residual  phi = %.3f  -> AR(1)-null p = %.4f  [conservative; break inflates phi]\n",
            phi_pool, p_ar1_pooled))
cat(sprintf("segmented-resid  phi = %.3f  -> AR(1)-null p = %.4f  [fair; autocorr net of break]\n",
            phi_seg,  p_ar1_seg))

# 3d. BLOCK-BOOTSTRAP break-date CI.
#     DGP = two-segment LINEAR-TREND fit at the canonical break (level+trend
#     model, matching the test); moving-block residual resample (L=4) preserves
#     short-run autocorrelation; re-find the canonical sup-F peak year each draw.
mb_resample <- function(res, n, L){                  # moving-block bootstrap
  nb <- ceiling(n/L); starts <- sample(seq_len(length(res)-L+1), nb, replace=TRUE)
  as.numeric(unlist(lapply(starts, function(s) res[s:(s+L-1)])))[1:n]
}
set.seed(SEED)
boot_block <- integer(BOOT)
for(b in seq_len(BOOT)){ ystar <- fitted_seg + mb_resample(resid_seg, n, BLKL)
  boot_block[b] <- supF_peakyear(ystar, yr) }
set.seed(SEED)                                        # iid residual bootstrap (comparison)
boot_iid <- integer(BOOT)
for(b in seq_len(BOOT)){ ystar <- fitted_seg + sample(resid_seg, n, replace=TRUE)
  boot_iid[b] <- supF_peakyear(ystar, yr) }
ci_block <- quantile(boot_block, c(0.05,0.95), type=1)
ci_iid   <- quantile(boot_iid,   c(0.05,0.95), type=1)
tb <- as.data.frame(table(boot_year=boot_block)); tb$boot_year<-as.integer(as.character(tb$boot_year))
tb$prop <- round(tb$Freq/BOOT,4)
mode_year <- tb$boot_year[which.max(tb$Freq)]
p_2016 <- mean(boot_block==2016); p_1517 <- mean(boot_block %in% 2015:2017)

# --- 18 Aug: CONCENTRATION, not just a percentile interval --------------------
# ⛔ The percentile CI is the WRONG summary for this distribution and it was making
#   the break look far worse located than it is. The draws are strongly UNIMODAL at
#   2015 with a long thin left tail: 23% of resamples scatter across 26 distinct
#   years, none holding more than 4%. A 5th-percentile cut therefore lands in the
#   tail (2000) and reports a 17-year "interval" across a region with almost no mass.
#   There is no secondary mode -- this is noise, not a rival break date.
# ⭐ Report the mode and the concentration instead. Both are computed here so the
#   chapter never has to retype them.
p_2015    <- mean(boot_block == 2015)
p_1416    <- mean(boot_block %in% 2014:2016)
p_1318    <- mean(boot_block %in% 2013:2018)
p_asympt  <- mean(boot_block %in% 2014:2018)   # coverage of the band the FIGURE draws
tail_pre13 <- mean(boot_block < 2013)
# narrowest CONTIGUOUS window that genuinely reaches 90%
.yy <- sort(unique(boot_block)); .best <- NULL
for (i in seq_along(.yy)) for (j in i:length(.yy)) {
  cv <- mean(boot_block >= .yy[i] & boot_block <= .yy[j])
  if (cv >= 0.90) { w <- .yy[j]-.yy[i]
    if (is.null(.best) || w < .best$w) .best <- list(w=w, lo=.yy[i], hi=.yy[j], cov=cv) } }
cat(sprintf("\n=== BOOTSTRAP CONCENTRATION (the honest summary) ===\n"))
cat(sprintf("P(2015)      = %.3f   <- modal by a factor of %.1f over the next year\n",
            p_2015, p_2015/sort(tb$Freq/BOOT, decreasing=TRUE)[2]))
cat(sprintf("P(2014-2016) = %.3f\nP(2013-2018) = %.3f\n", p_1416, p_1318))
cat(sprintf("P(2014-2018) = %.3f   <- ACTUAL coverage of the band Figure 2.16 draws\n", p_asympt))
cat(sprintf("left tail <2013 = %.3f over %d distinct years, max any one year %.3f\n",
            tail_pre13, length(unique(boot_block[boot_block<2013])),
            max(tb$Freq[tb$boot_year<2013])/BOOT))
cat(sprintf("narrowest genuine 90%% contiguous band = [%d, %d] (%d years, cov %.3f)\n",
            .best$lo, .best$hi, .best$w+1, .best$cov))
write.csv(tb[order(tb$boot_year),c("boot_year","Freq","prop")],
          file.path(OUT,"canonical_bootstrap_distribution.csv"), row.names=FALSE)
cat(sprintf("\n=== BLOCK-BOOTSTRAP break-date CI (L=%d, B=%d) ===\n", BLKL, BOOT))
cat(sprintf("point estimate = %d; bootstrap mode = %d\n", CS$peak_year, mode_year))
cat(sprintf("90%% CI (block) = [%d, %d];  (iid) = [%d, %d]\n", ci_block[1],ci_block[2],ci_iid[1],ci_iid[2]))
cat(sprintf("P(break=2016) = %.3f; P(break in 2015-2017) = %.3f\n", p_2016, p_1517))

# 3e. BAI-PERRON multiple-break selection (BIC), mean-shift model, h=0.15
ts_pc1 <- ts(yy, start=min(yr))
bp <- breakpoints(ts_pc1 ~ 1, h=0.15)
bp_years <- if(all(is.na(bp$breakpoints))) integer(0) else yr[bp$breakpoints]
bp_bic <- summary(bp)$RSS["BIC",]
cat(sprintf("\n=== BAI-PERRON (breakpoints ~1, h=0.15, BIC) ===\n"))
cat("BIC-selected break year(s):", if(length(bp_years)) paste(bp_years,collapse=", ") else "none", "\n")
cat("BIC by #breaks:\n"); print(round(bp_bic,2))

# 3f. SECONDARY (~2000) break?  Largest local peak of the canonical F-sweep in
#     the pre-2010 region, plus the 2-break Bai-Perron solution.
pre <- CS$curve[CS$curve$year <= 2010,]
sec_year <- pre$year[which.max(pre$F)]; sec_F <- max(pre$F)
bp2 <- yr[breakpoints(bp, breaks=2)$breakpoints]
cat(sprintf("\n=== SECONDARY break scan ===\n"))
cat(sprintf("Largest pre-2010 sup-F peak: %d (F = %.2f)\n", sec_year, sec_F))
cat("Bai-Perron 2-break solution:", paste(bp2, collapse=", "), "\n")

# ---- one machine-readable break-result table -------------------------------
break_res <- data.frame(
  metric = c("break_year_canonical","supF_level_trend_WALD","supF_level_trend_df2","supF_5pct_crit_df2",
             "perm_p_iid","perm_p_ar1_pooled_conservative","perm_p_ar1_seg_fair",
             "ar1_phi_pooled","ar1_phi_seg","meanshift_break_year","meanshift_supF_df1",
             "boot_ci90_lo_block","boot_ci90_hi_block","boot_ci90_lo_iid","boot_ci90_hi_iid",
             "boot_mode","P_break_2016","P_break_2015_2017",
             "P_break_2015","P_break_2014_2016","P_break_2013_2018",
             "coverage_of_figure_band_2014_2018","boot_tailmass_pre2013",
             "genuine90_band_lo","genuine90_band_hi",
             "baiperron_breaks","baiperron_2break_sol","secondary_pre2010_year","secondary_pre2010_F",
             "n","seed","nperm","nsim","boot_B","block_len"),
  value  = c(CS$peak_year, round(2*CS$peak_F,3), round(CS$peak_F,3), round(CS$crit_5pct,3),
             round(CS$perm_p,4), round(p_ar1_pooled,4), round(p_ar1_seg,4),
             round(phi_pool,3), round(phi_seg,3), MS$peak_year, round(MS$peak_F,3),
             ci_block[1], ci_block[2], ci_iid[1], ci_iid[2],
             mode_year, round(p_2016,4), round(p_1517,4),
             round(p_2015,4), round(p_1416,4), round(p_1318,4),
             round(p_asympt,4), round(tail_pre13,4), .best$lo, .best$hi,
             if(length(bp_years)) paste(bp_years,collapse=";") else "none",
             paste(bp2,collapse=";"), sec_year, round(sec_F,3),
             CS$n, SEED, NPERM, NSIM, BOOT, BLKL),
  stringsAsFactors=FALSE)
write.csv(break_res, file.path(OUT,"canonical_break_result.csv"), row.names=FALSE)

# ============================================================================
# 4. LEAVE-ONE-OUT across the six components
# ============================================================================
loo <- do.call(rbind, lapply(COMPS, function(drop){
  keep <- setdiff(COMPS, drop)
  p <- run_pca(panel, paste0(keep,"_z"))
  m <- merge(data.frame(year=p$years,pc1=p$pc1), data.frame(year=P$years,full=P$pc1), by="year")
  cs <- chow_sweep(year=p$years, y=p$pc1, trim=0.15, nperm=2000, seed=SEED)
  data.frame(dropped=drop, n=p$n, cor_with_full=round(cor(m$pc1,m$full),4),
             pc1_var_pct=round(100*p$var_exp[1],2),
             break_year=cs$peak_year, supF=round(cs$peak_F,2), perm_p=round(cs$perm_p,4),
             stringsAsFactors=FALSE)
}))
write.csv(loo, file.path(OUT,"canonical_leave_one_out.csv"), row.names=FALSE)
cat("\n=== LEAVE-ONE-OUT (drop each of the six) ===\n"); print(loo, row.names=FALSE)

# ============================================================================
# 5. COMPARISON TO THE OLD DEFEATS-BASED LIVE COMPOSITE
# ============================================================================
old <- read.csv(file.path(PCR,"turbulence_pca_1979_2025_FINAL.csv"), stringsAsFactors=FALSE)
old <- old[!is.na(old$PC1_index), c("year","PC1_index")]
mrg <- merge(data.frame(year=P$years, new=P$pc1), old, by="year")
r_old <- cor(mrg$new, mrg$PC1_index)
old_cs <- chow_sweep(year=old$year, y=old$PC1_index, trim=0.15, nperm=NPERM, seed=SEED)  # same canonical test
old_ms <- supF_meanshift(old$PC1_index, old$year)
old_load <- read.csv(file.path(PCR,"pca_loadings_FINAL.csv"), stringsAsFactors=FALSE)
cmp <- data.frame(
  composite = c("OLD (live, defeats-based)","NEW (canonical clean-six)"),
  components = c("pm_churn+defeats_py+rebellion_pct+elect_vol+spending_churn",
                 "elect_vol+pm_churn+rebellion_pct+dislocation+dept_churn+uturns"),
  pc1_var_pct = c(old_load$var_explained_PCn[1], round(100*P$var_exp[1],2)),
  break_year_leveltrend = c(old_cs$peak_year, CS$peak_year),
  supF_leveltrend = c(round(old_cs$peak_F,2), round(CS$peak_F,2)),
  perm_p_iid = c(round(old_cs$perm_p,4), round(CS$perm_p,4)),
  supF_meanshift = c(round(old_ms$peak_F,2), round(MS$peak_F,2)),
  r_new_vs_old = c(NA, round(r_old,4)),
  stringsAsFactors=FALSE)
write.csv(cmp, file.path(OUT,"canonical_vs_old_comparison.csv"), row.names=FALSE)
cat("\n=== NEW vs OLD (same canonical test) ===\n"); print(cmp, row.names=FALSE)
cat(sprintf("\nPearson r(new PC1, old live PC1), %d common years = %.4f\n", nrow(mrg), r_old))

# ============================================================================
# 6. FIGURES (house style)
# ============================================================================
# 6a. canonical 2-panel Chow figure via the standardised helper
try(chow_panel_figure(CS, series_label="Canonical turbulence composite (clean six), 1979-2024",
      y_label="PC1 turbulence index (higher = more turbulent)",
      source_note="Level+trend sup-F (df1=2), canonical chow_sweep. Clean-five composite.",
      outfile=file.path(OUT,"fig_canonical_chow.png")), silent=TRUE)

# 6b. PC1 with break line + 90% bootstrap band, new vs old overlay
png(file.path(OUT,"fig_canonical_pc1.png"), width=1200, height=720, res=130)
par(mar=c(4.5,4.5,3.6,1))
plot(series$year, series$PC1_index, type="o", pch=19, col="#1F3864", lwd=2,
     xlab="Year", ylab="PC1 turbulence index (higher = more turbulent)",
     main="Canonical turbulence composite (clean six), PC1 1979-2024")
rect(ci_block[1], par("usr")[3], ci_block[2], par("usr")[4], col="#d7191c18", border=NA)
abline(v=CS$peak_year, lty=2, col="#d7191c", lwd=2)
lines(mrg$year, mrg$PC1_index, col="#999999", lwd=1.6, lty=3)
legend("topleft", bty="n", cex=0.85,
  legend=c("Canonical clean-six PC1", "OLD live composite PC1",
           paste0("Canonical break ",CS$peak_year),
           sprintf("90%% bootstrap band [%d-%d]",ci_block[1],ci_block[2])),
  col=c("#1F3864","#999999","#d7191c","#d7191c88"), lty=c(1,3,2,1), lwd=c(2,1.6,2,6))
dev.off()

# ============================================================================
# 7. FREEZE — save full run object
# ============================================================================
saveRDS(list(pca=P, chow=CS, meanshift=MS,
             p_ar1_pooled=p_ar1_pooled, p_ar1_seg=p_ar1_seg,
             ar1=list(phi_pool=phi_pool, phi_seg=phi_seg, sd_pool=sd_pool, sd_seg=sd_seg),
             boot_block=boot_block, boot_iid=boot_iid,
             ci_block=ci_block, ci_iid=ci_iid, mode_year=mode_year,
             p_2016=p_2016, p_1517=p_1517,
             baiperron=bp_years, baiperron_2=bp2, bp_bic=bp_bic,
             secondary=c(year=sec_year,F=sec_F),
             loo=loo, comparison=cmp, r_vs_old=r_old,
             seed=SEED, years=YEARS, comps=COMPS, load=load_tab, var=var_tab,
             break_result=break_res),
        file.path(OUT,"canonical_run_summary.rds"))

cat("\n=== DONE. Canonical composite frozen to", OUT, "===\n")
sink()
